import{_ as p,a0 as a,w as i,s as d,ao as r,I as e,x as o,a1 as u,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何正确双启动Ubuntu和Windows双系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何正确双启动Ubuntu和Windows双系统 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何正确双启动Ubuntu和Windows双系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何正确双启动Ubuntu和Windows双系统 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/How to Dual Boot Ubuntu and Windows Properly","title":"如何正确双启动Ubuntu和Windows双系统","tag":"201401","desc":""},"relativePath":"201401/How to Dual Boot Ubuntu and Windows Properly.md","filePath":"[post].md"}'),l={name:"201401/How to Dual Boot Ubuntu and Windows Properly.md"};function w(b,t,m,U,W,T){const n=a("Link");return i(),d("div",null,[t[11]||(t[11]=r(`<h1 id="如何正确双启动ubuntu和windows双系统" tabindex="-1">如何正确双启动Ubuntu和Windows双系统 <a class="header-anchor" href="#如何正确双启动ubuntu和windows双系统" aria-label="Permalink to “如何正确双启动Ubuntu和Windows双系统”">​</a></h1><p><strong>尽管微软想让你信任Windows，但一个Linux操作系统和一个Windows操作系统可以在同一台PC上和平共存。这个文章会指导你如何让一个Ubuntu系统和Windows操作系统并行运行。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Dual-Boot-Ubuntu-and-Windows-Properly-415377-2.jpg" alt=""></p><p>你必须考虑两种场景，同时你也必须决定哪一种适合你。这里必须要考虑安装顺序。在你已经安装好Ubuntu操作系统后再安装Windows会有一点问题，因为微软似乎不太在意其他小伙伴。</p><p>如果你是在已经安装好Windows后安装Ubuntu，那么事情会变得简单多了，几乎没有任何工作和准备是必需的。</p><p>让我们开始处理更加困难的问题。如果你已经有一个Ubuntu系统，想安装Windows，你会丢掉GRUB，它是默认的引导程序。Windows不会在意它，并会擦除它。</p><p>如果你已经犯了这个错误，但你并没有重写Linux分区，请别沮丧。数据仍然在那里，你需要的是一个含有Ubuntu（最新到13.10版本）的可启动live CD。你需要安装一个名为Boot-Repair的应用程序，使用PPA来安装它。</p><p>记住，如果你使用U盘，安装应用会相当简单，因为Ubuntu安装镜像是混合镜像。用Live CD启动一个Ubuntu会话，打开终端，然后输入下列指令：</p><pre><code>sudo add-apt-repository ppa:yannubuntu/boot-repair &amp;&amp; sudo apt-get update
sudo apt-get install -y boot-repair &amp;&amp; (boot-repair &amp;)
</code></pre><p>打开应用程序，点击推荐修复，然后等待。在这个步骤完成后，重启机器，你就会重新看到GRUB，实现双启动。</p><p>在另一方面，如果你已经安装好Windows，想要安装Ubuntu，事情会更加简单。启动Ubuntu安装，选择安装到一个非Windows分区，格式化为EXT4，选择引导程序的位置，然后就搞定了。</p><p>如果你选择将引导程序安装在和Windows安装的同一块硬盘上，它会擦除微软的引导程序。这样没有问题，因为GRUB会识别出WIndows操作系统，你不会丢掉它。如果你把它安装在其它地方，譬如在另一块硬盘上，当你选择从不同的硬盘启动时，你会看到它们两个。</p><p>开始享受你的Ubuntu和Windows双系统启动的乐趣吧！</p><hr>`,14)),e("p",null,[t[1]||(t[1]=o("via: ",-1)),u(n,{href:"http://news.softpedia.com/news/How-to-Dual-Boot-Ubuntu-and-Windows-Properly-415377.shtml"},{default:s(()=>[...t[0]||(t[0]=[o("http://news.softpedia.com/news/How-to-Dual-Boot-Ubuntu-and-Windows-Properly-415377.shtml",-1)])]),_:1})]),e("p",null,[t[4]||(t[4]=o("译者：",-1)),u(n,{href:"https://github.com/KayGuoWhu"},{default:s(()=>[...t[2]||(t[2]=[o("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=o(" 校对：",-1)),u(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=o("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原创翻译，",-1)),u(n,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[o("Linux中国",-1)])]),_:1}),t[10]||(t[10]=o(" 荣誉推出",-1))])])}const P=p(l,[["render",w]]);export{x as __pageData,P as default};
